const response = $input.item.json;

// Gemini retorna em candidates[0].content.parts[0].text
const content = (
  response?.candidates?.[0]?.content?.parts?.[0]?.text ||
  response?.choices?.[0]?.message?.content ||
  ""
);

// Limpa escapes que o Gemini às vezes adiciona
const cleaned = content
  .replace(/\\n/g, '\n')
  .replace(/\\"/g, '"')
  .replace(/\\\\/g, '\\');

const match = cleaned.match(/<expense>([\s\S]*?)<\/expense>/);

if (!match) {
  throw new Error(`Resposta da IA nao contem bloco <expense>...</expense>: ${cleaned.substring(0, 200)}`);
}

let expenseJson;
try {
  expenseJson = JSON.parse(match[1].trim());
} catch (e) {
  throw new Error(`JSON invalido dentro do bloco expense: ${e.message}\nConteudo: ${match[1].substring(0, 200)}`);
}

const mensagemUsuario = cleaned.split('<expense>')[0].trim();

return {
  json: {
    expense: expenseJson,
    mensagem_usuario: mensagemUsuario || expenseJson.mensagem_usuario,
    session_id: $('Preparar Contexto').item.json.session_id,
    wa_id: $('Preparar Contexto').item.json.wa_id,
    phone: $('Preparar Contexto').item.json.phone,
  }
};

const contexto = $("Preparar Contexto").item.json;
const parsed = $("Extrair Bloco Expense").item.json.expense;
const sessaoResp = $input.item.json;
const usuarioId = Array.isArray(sessaoResp) ? (sessaoResp[0] && sessaoResp[0].usuario_id) : (sessaoResp && sessaoResp.usuario_id);

if (!usuarioId) {
  throw new Error("Sessao " + contexto.session_id + " ainda nao tem usuario_id vinculado (onboarding pendente)");
}

// Defesa em profundidade contra classificacao errada da IA. A coluna valor tem
// constraint valor > 0 (recibos_valor_positivo_chk) e o node de insert nao trata
// erro: a violacao derruba a execucao ANTES do node que responde no WhatsApp, e
// a pessoa fica sem recibo E sem resposta nenhuma.
//
// Nao e hipotese: quando chega aqui um texto que nao descreve despesa — uma
// resposta de follow-up que nao foi reconhecida como resposta, por exemplo — o
// Gemini devolve valor 0 tentando dar sentido a mensagem.
const valorBruto = parsed.valor === null || parsed.valor === undefined ? "" : parsed.valor;
const valorNumero = typeof valorBruto === "number"
  ? valorBruto
  : Number(String(valorBruto).replace(/\s/g, "").replace(",", "."));
const valorValido = Number.isFinite(valorNumero) && valorNumero > 0;

// A mensagem existe para o caso invalido nao virar silencio. Ela pede a despesa
// inteira de novo, e nao so o valor: sem recibo gravado nao ha lancamento ao
// qual um valor solto pudesse se juntar.
const mensagemValorInvalido = "Não consegui identificar o valor dessa despesa, então não registrei nada.\n\nSe for um lançamento, me manda de novo com o valor junto — por exemplo: \"dentista 500 reais\".";

// Data inferida: mensagem sem referencia temporal nao gera pergunta de volta
// (a maioria das mensagens nao cita data mesmo sendo do dia). Cai na data de
// recebimento e fica marcada em metadados_ia.data_inferida, que e so rastro de
// auditoria. A linha de status abaixo le requer_revisao_humana e NAO le
// data_inferida: data inferida sozinha nunca manda para revisao humana.
const dataRecebimento = contexto.data_recebimento || null;
const dataDaIa = parsed.data_despesa || null;
const dataDespesa = dataDaIa || dataRecebimento;
const dataInferida = dataDaIa ? parsed.data_inferida === true : Boolean(dataRecebimento);

// A IA pode listar a data em campos_ausentes apesar da regra do prompt. Com a
// data preenchida por inferencia ela deixa de ser pendencia de auditoria.
const camposAusentes = (parsed.campos_ausentes || []).filter(
  (campo) => !dataInferida || !/^data/i.test(String(campo))
);

// Campos de identificacao que valem uma pergunta. Espelho de
// derivarCamposBloqueantes em supabase/functions/_shared/followup.ts;
// tests/n8n_campos_bloqueantes_test.ts compara os dois lado a lado.
//
// A lista e DERIVADA aqui, e nao lida da IA. O campo campos_bloqueantes saiu do
// schema do prompt porque a definicao dele — "o campo que SOZINHO removeria a
// revisao" — era irrealizavel exatamente onde a pergunta mais valia: faltando
// documento E estabelecimento, nenhum dos dois sozinho satisfaz, e o modelo
// devolvia [] com razao (10/10 execucoes contra o Gemini real). O juizo que
// sobra para a IA e o destino, em deducibilidade_se_desbloqueado.
const CAMPOS_FOLLOWUP = ["documento_prestador", "estabelecimento"];
const destino = ["DEDUTIVEL", "PARCIALMENTE_DEDUTIVEL"].includes(
  parsed.deducibilidade_se_desbloqueado
)
  ? parsed.deducibilidade_se_desbloqueado
  : null;
const campoVazio = (valor) =>
  valor === null || valor === undefined || String(valor).trim() === "";

// No maximo um campo: a regra fiscal de SAUDE pede identificacao do prestador
// OU do estabelecimento, entao o CNPJ ja satisfaz o requisito inteiro, e o
// follow-up so pergunta uma coisa — lista maior nunca esvaziaria e a promocao
// ficaria esperando resposta que ninguem pediu.
const bloqueantes = destino
  ? CAMPOS_FOLLOWUP.filter((campo) => campoVazio(parsed[campo])).slice(0, 1)
  : [];

const metadadosIa = {
  ...parsed,
  data_despesa: dataDespesa,
  data_inferida: dataInferida,
  campos_ausentes: camposAusentes,
  campos_bloqueantes: bloqueantes,
  data_despesa_original_ia: dataDaIa,
  data_recebimento_mensagem: dataRecebimento,
};

const status = parsed.requer_revisao_humana ? "REVISAO_HUMANA" : "RECEBIDO";

// Follow-up conversacional (fase 13). So vale para despesa que ficou em
// revisao por falta de campo ESTRUTURADO e objetivamente respondivel: o campo
// sai da derivacao acima, que so produz alguma coisa quando a IA declarou um
// destino de promocao. Ambiguidade de categoria fiscal nunca entra aqui.
//
// A pergunta e anexada a confirmacao, nao a substitui: a despesa JA foi
// gravada e confirmada, e ignorar a pergunta nao trava nada.
const followupCampo = status === "REVISAO_HUMANA" ? (bloqueantes[0] || null) : null;

// Espelho de perguntaParaCampo em supabase/functions/_shared/followup.ts;
// tests/n8n_fase13_test.ts compara os dois textos.
function perguntaParaCampo(campo, estabelecimento) {
  if (campo === "documento_prestador") {
    const onde = (estabelecimento || "").trim();
    return onde
      ? "Para confirmar se é dedutível, você tem o CNPJ ou CPF de " + onde + "?"
      : "Para confirmar se é dedutível, você tem o CNPJ ou CPF do prestador?";
  }
  return "Para confirmar se é dedutível, onde foi essa despesa? Pode me dizer o nome do estabelecimento.";
}

const followupPergunta = followupCampo
  ? perguntaParaCampo(followupCampo, parsed.estabelecimento)
  : null;

const mensagemBase = $("Extrair Bloco Expense").item.json.mensagem_usuario;

// Pendencia anterior substituida (fase 14). So ha substituicao quando ESTA
// despesa cria pendencia: sem followupPergunta a RPC nem e chamada e a pergunta
// antiga continua viva, entao nao ha o que avisar.
//
// O aviso nao convida a responder a antiga depois, e a ausencia do convite e o
// ponto: a pendencia antiga esta fechada e a unica aberta passa a ser a desta
// despesa, entao um documento enviado mais tarde seria gravado NESTE recibo.
// Prometer o canal colaria evidencia no recibo errado — pior do que o silencio
// que isto corrige. Fila de multiplas pendencias e outra fase.
//
// Espelho de AVISO_PENDENCIA_SUBSTITUIDA em
// supabase/functions/_shared/followup.ts; tests/n8n_fase14_test.ts compara os
// dois textos.
const avisoPendenciaSubstituida =
  "A pergunta da despesa anterior ficou sem resposta — ela continua registrada e vai para a revisão do contador.";
const substituiuPendencia = Boolean(followupPergunta && contexto.followup_anterior_id);

const mensagemFinal = [
  mensagemBase,
  substituiuPendencia ? avisoPendenciaSubstituida : null,
  followupPergunta,
].filter(Boolean).join("\n\n");

return {
  json: {
    usuario_id: usuarioId,
    sessao_whatsapp_id: contexto.session_id,
    origem: contexto.origem,
    status,
    descricao: parsed.descricao,
    estabelecimento: parsed.estabelecimento || null,
    documento_prestador: parsed.documento_prestador || null,
    data_despesa: dataDespesa,
    valor: valorValido ? valorNumero : null,
    categoria: parsed.categoria,
    deducibilidade: parsed.deducibilidade,
    justificativa_deducibilidade: parsed.justificativa_deducibilidade || null,
    confidence_score: parsed.confidence_score,
    requer_revisao_humana: parsed.requer_revisao_humana,
    possui_indicio_tuss_cbhpm: parsed.possui_indicio_tuss_cbhpm || false,
    codigos_medicos_identificados: parsed.codigos_medicos_identificados || [],
    termos_auditoria_identificados: parsed.termos_auditoria_identificados || [],
    arquivo_hash_sha256: contexto.media_sha256 || null,
    metadados_ia: metadadosIa,
    mensagem_usuario: mensagemFinal,
    followup_campo: followupCampo,
    followup_pergunta: followupPergunta,
    followup_substituiu_anterior: substituiuPendencia,
    valor_valido: valorValido,
    mensagem_valor_invalido: mensagemValorInvalido,
    wa_id: contexto.wa_id,
  },
};
